import { JxInput, JxButton, JxToast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [toastOpen, setToastOpen] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!email) return;
    setEmail('');
    setToastOpen(true);
  };

  return (
    <>
      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', gap: 'var(--jx-space-sm)', alignItems: 'flex-end' }}
      >
        <JxInput
          type="email"
          name="email"
          label="Email"
          placeholder="you@example.com"
          value={email}
          onValueChange={setEmail}
          required
        />
        <JxButton type="submit" variant="primary">
          Подписаться
        </JxButton>
      </form>

      <JxToast
        open={toastOpen}
        onOpenChange={setToastOpen}
        variant="success"
        position="top-right"
        title="Готово"
        description="Письмо с подтверждением подписки отправлено на указанный адрес."
        duration={4000}
      />
    </>
  );
}

